    const expected = [first, second];
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    for (const route of ['/', `/projects/${first.id}`]) {
      const response = await fetch(base + route);
      assert.equal(response.status, 200);
      assert.match(await response.text(), /<label for="project-name">Project name<\/label>/);
    }
    assert.equal((await fetch(`${base}/api/projects/999999`)).status, 404);
    await stop();
    await start();
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), expected);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
  } finally {
    await stop();
    await rm(dir, { recursive: true, force: true });
  }
});

:root { font-family: system-ui, sans-serif; color: #172334; background: #f4f6fa; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 24px; }
h1 { margin-top: 0; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.form-controls { display: flex; gap: 12px; flex-wrap: wrap; }
input { flex: 1; min-width: 180px; padding: 10px; border: 1px solid #7d8a9c; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #234ea1; color: white; font: inherit; cursor: pointer; }
button:hover { background: #183a7b; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #bf7c00; outline-offset: 3px; }
#projects { margin-top: 28px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px; margin-bottom: 12px; background: white; border: 1px solid #d8dfea; border-radius: 8px; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row button { flex-shrink: 0; }
[role="alert"] { color: #9e2020; }
[hidden] { display: none !important; }

